'use client'

import Link from 'next/link'
import { memo, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import {
  buildStageRows,
  monthAtFraction,
  nowFraction,
  type StageAmbient,
  type StageBlock,
  type StageRow,
} from '@/lib/program-stage'
import { MONTH_NAMES_LONG, MONTH_NAMES_SHORT } from '@/lib/program-schedule'
import type { Division, DivisionCode, Program } from '@/types/content'

/*
 * Papan tahun /program-kerja.
 *
 * Satu periode kerja digambar sebagai delapan pita mendatar. Sumbu mendatarnya
 * waktu, sumbu tegaknya bidang, dan tiap balok adalah satu program di tempat ia
 * benar-benar jatuh. Menyentuh satu balok meredupkan seluruh papan kecuali baris
 * pemiliknya, dan bacaannya muncul MENEMPEL DI BALOKNYA.
 *
 * Soal tempat bacaan itu sudah dua kali salah, dan ini catatan supaya tidak
 * salah untuk ketiga kalinya.
 *
 * Versi pertama menaruh bacaan sebagai panel diam di pojok kanan atas, dengan
 * alasan yang terdengar benar: tooltip melayang menutupi balok sebelahnya, dan
 * di papan sepadat ini itu berarti menutupi jawabannya. Alasan itu benar tapi
 * tidak lengkap, karena papannya sendiri 768px, lebih tinggi dari layar laptop.
 * Begitu pembaca melihat baris keenam, panel di pojok itu sudah keluar layar
 * dan satu-satunya cara membacanya adalah menggulir ke atas — yang otomatis
 * melepaskan kursor dari baloknya, sehingga bacaannya kembali kosong. Panel itu
 * bukan cuma jauh; ia mustahil dipakai.
 *
 * Sekarang bacaannya menempel di balok. Keberatan lama tetap dijawab, tapi
 * lewat jalan lain: menyentuh satu balok sudah meredupkan tujuh baris lain jadi
 * 20%, jadi yang tertutup kartu memang sedang tidak sedang dibaca siapa pun.
 * Kartunya juga membalik ke atas atau ke bawah tergantung ruang, dan
 * pointer-events-nya mati supaya tidak pernah merebut kursor dari baloknya.
 *
 * Pojok kanan atas sekarang diisi LEGENDA, dan itu keterangan yang selama ini
 * hilang: tidak ada satu pun tempat di halaman ini yang menjelaskan kenapa
 * sebagian balok lebih tebal dari yang lain.
 *
 * Aturan yang mengikat berkas ini:
 * 1. Isi papan tampil penuh sebelum satu baris skrip pun jalan. Animasi masuk
 *    hanya dinyalakan setelah komponen hidup, lewat data-animate. Halaman yang
 *    dirender tanpa JavaScript, atau di tab yang tidak aktif, tetap lengkap.
 * 2. Tiap balok adalah tautan sungguhan. Papan ini bisa ditelusuri dengan Tab,
 *    dan fokus keyboard melakukan persis yang dilakukan kursor.
 * 3. Warna bidang membawa arti, bukan hiasan. Rona yang sama dipakai untuk
 *    bidang yang sama di seluruh halaman.
 * 4. Semua yang diletakkan di sumbu waktu — balok, garis hari ini, penunjuk
 *    kursor — diukur terhadap AREA BULAN, bukan terhadap lebar papan. Lihat
 *    catatan di fractionFromEvent().
 */

type ProgramYearStageProps = {
  divisions: Division[]
  programsByDivision: Record<DivisionCode, Program[]>
  year: number
}

type Reading =
  | { kind: 'idle' }
  | {
      kind: 'block'
      block: StageBlock
      division: Division
      /** Semua dalam ruang koordinat .stg-field, satuan piksel. */
      x: number
      /** Tepi atas dan bawah BALOKNYA, bukan kartunya. */
      top: number
      bottom: number
    }

/*
 * Geometri jalur.
 *
 * Tinggal di sini DAN dipakai CSS lewat custom property, bukan ditulis dua kali.
 * Sebelumnya angka 30 dan 5 ada di berkas ini sementara `top: calc(var(--lane) *
 * 35px)` dan `height: 30px` ada di CSS, jadi mengubah tinggi jalur berarti
 * mengubah dua berkas yang tidak saling menyebut. Sekali salah satu lupa
 * diperbarui, balok dan barisnya melenceng tanpa ada yang error.
 */
const LANE_HEIGHT = 28
const LANE_GAP = 5

const CARD_WIDTH = 300

/** Jarak kartu ke baloknya. */
const CARD_OFFSET = 10

/*
 * useLayoutEffect memperingatkan saat komponen ini dirender di server, dan
 * peringatannya benar: tidak ada tata letak untuk diukur di sana. Yang dipakai
 * di server cuma versi tanpa efek. Di browser tetap harus layout effect, karena
 * mengukur kartu setelah cat berarti kartu sempat terlihat di tempat sementara.
 */
const useMeasureEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect

export function ProgramYearStage({ divisions, programsByDivision, year }: ProgramYearStageProps) {
  const rows = useMemo(
    () => buildStageRows({ divisions, programsByDivision, year }),
    [divisions, programsByDivision, year],
  )

  const [reading, setReading] = useState<Reading>({ kind: 'idle' })
  const [sweep, setSweep] = useState<number | null>(null)
  const [isLive, setIsLive] = useState(false)
  const fieldRef = useRef<HTMLDivElement>(null)

  /*
   * Animasi masuk dinyalakan setelah cat pertama, bukan lewat kelas awal.
   *
   * Kalau balok lahir dalam keadaan menciut lalu mengembang lewat transisi,
   * halaman yang dirender di tab tersembunyi atau oleh perayap tanpa layar akan
   * terbit dengan papan kosong: transisi tidak pernah berjalan, dan tidak ada
   * yang mengembalikannya. Jadi keadaan bawaan adalah tampil penuh, dan skrip
   * ini cuma menambah gerak di atas sesuatu yang sudah benar.
   */
  useEffect(() => {
    const frame = window.requestAnimationFrame(() => setIsLive(true))
    return () => window.cancelAnimationFrame(frame)
  }, [])

  const now = useMemo(() => nowFraction(year), [year])
  const totalPrograms = rows.reduce((sum, row) => sum + row.total, 0)
  const drawnBlocks = rows.reduce((sum, row) => sum + row.blocks.length, 0)
  const ambientCount = rows.reduce((sum, row) => sum + row.ambient.length, 0)
  const deferredCount = rows.reduce((sum, row) => sum + row.deferred.length, 0)
  const exactCount = rows.reduce(
    (sum, row) => sum + row.blocks.filter((block) => block.precision === 'exact').length,
    0,
  )

  /**
   * Lebar kolom label baris, dibaca dari CSS.
   *
   * Angkanya berbeda antara layar lebar dan sempit (94px lawan 54px), jadi ia
   * tidak boleh ditulis ulang di sini. Dibaca sekali per gerakan, dan itu murah:
   * getComputedStyle di sini tidak memicu layout ulang karena rect papannya
   * memang sudah diminta di baris sebelumnya.
   */
  function readLabelWidth(field: HTMLElement) {
    const raw = getComputedStyle(field).getPropertyValue('--label-w')
    const parsed = Number.parseFloat(raw)
    return Number.isFinite(parsed) ? parsed : 0
  }

  /*
   * Fraksi tahun di bawah kursor.
   *
   * Versi lama menghitungnya sebagai (clientX - kiri papan) / lebar papan, dan
   * itu keliru: papan punya kolom label selebar 94px di kirinya yang BUKAN
   * bagian dari sumbu waktu. Akibatnya penunjuk bulan meleset hampir satu bulan
   * penuh di awal tahun (di tepi kiri kolom Januari ia menulis "Februari"), dan
   * kesalahan yang sama menggeser garis "Hari ini" sekitar 38px dari tanggal
   * sebenarnya. Dua-duanya salah tanpa pernah terlihat rusak, yang justru
   * bentuk kesalahan paling buruk untuk sebuah kalender.
   */
  function fractionFromEvent(event: React.PointerEvent<HTMLDivElement>) {
    const field = fieldRef.current
    if (!field) return null

    const bounds = field.getBoundingClientRect()
    const labelWidth = readLabelWidth(field)
    const axisWidth = bounds.width - labelWidth
    if (axisWidth <= 0) return null

    const fraction = (event.clientX - bounds.left - labelWidth) / axisWidth
    return Math.min(1, Math.max(0, fraction))
  }

  function handlePointerMove(event: React.PointerEvent<HTMLDivElement>) {
    // Sapuan kursor tidak punya arti di layar sentuh: jari tidak melayang, dan
    // menggeser papan ke samping akan menyeret garisnya ikut-ikutan.
    if (event.pointerType !== 'mouse') return

    setSweep(fractionFromEvent(event))
  }

  /*
   * Mengubah balok yang disentuh jadi posisi kartu, dalam ruang koordinat papan.
   *
   * Diukur dari DOM, bukan dihitung ulang dari from/to/lane. Tinggi tiap baris
   * bergantung pada jumlah jalurnya, jadi menghitung posisi tegak sebuah balok
   * berarti menjumlahkan tinggi semua baris di atasnya — yaitu menyalin ulang
   * tata letak yang sudah diketahui peramban dengan pasti.
   */
  const readBlock = useCallback((block: StageBlock, division: Division, element: HTMLElement) => {
    const field = fieldRef.current
    if (!field) return

    const fieldRect = field.getBoundingClientRect()
    const rect = element.getBoundingClientRect()

    const half = CARD_WIDTH / 2 + 8

    setReading({
      kind: 'block',
      block,
      division,
      // Dijepit supaya kartu tidak pernah menonjol keluar papan dan menambah
      // lebar gulir mendatar pada wadahnya.
      x: Math.min(Math.max(rect.left - fieldRect.left + rect.width / 2, half), fieldRect.width - half),
      top: rect.top - fieldRect.top,
      bottom: rect.bottom - fieldRect.top,
    })
  }, [])

  const clearBlock = useCallback(() => setReading({ kind: 'idle' }), [])

  /*
   * Tempat tegak kartu, DIUKUR bukan ditaksir.
   *
   * Ini pernah dikerjakan dengan tinggi kartu yang ditebak sebagai tetapan, dan
   * tebakan itu meleset persis di kartu yang paling panjang: program berulang
   * membawa satu baris catatan tambahan, kartunya jadi 231px sementara
   * tebakannya 210, dan kartu itu terpotong 18px oleh tepi papan. Menaikkan
   * tetapannya cuma memindahkan ambang salahnya, tidak menghapusnya — teks
   * program datang dari panel dan panjangnya tidak dibatasi apa pun.
   *
   * Wadah papan memakai overflow-x: auto, dan itu memaksa sumbu tegaknya ikut
   * memotong (CSS tidak mengizinkan satu sumbu auto sementara sumbu lain
   * visible), jadi kartu yang menyembul memang benar-benar terpotong, bukan
   * melayang di atas halaman.
   *
   * useLayoutEffect, bukan useEffect: ia berjalan setelah DOM berubah tapi
   * SEBELUM cat, jadi kartu tidak pernah sempat terlihat di tempat sementara.
   * Selama posisinya belum dihitung, kartunya disembunyikan lewat visibility.
   */
  const cardRef = useRef<HTMLDivElement>(null)
  const [cardTop, setCardTop] = useState<number | null>(null)

  useMeasureEffect(() => {
    if (reading.kind !== 'block') {
      setCardTop(null)
      return
    }

    const card = cardRef.current
    const field = fieldRef.current
    if (!card || !field) return

    const height = card.offsetHeight
    const limit = field.clientHeight
    const below = reading.bottom + CARD_OFFSET
    const above = reading.top - CARD_OFFSET - height

    if (below + height <= limit) {
      setCardTop(below)
      return
    }

    // Tidak muat di bawah. Di atas kalau muat; kalau dua-duanya tidak muat
    // (papan pendek, kartu panjang), tempelkan ke tepi bawah papan — terjepit
    // masih terbaca, terpotong tidak.
    setCardTop(above >= 0 ? above : Math.max(0, limit - height))
  }, [reading])

  const sweepMonth = sweep === null ? null : monthAtFraction(sweep)
  const activeDivision = reading.kind === 'block' ? reading.division.code : null

  // Penunjuk kursor padam saat sebuah balok sedang dibaca. Dua penanda yang
  // saling menimpa di area yang sama cuma menambah keramaian, dan yang sedang
  // dijawab sudah bukan "ini bulan apa" melainkan "ini program apa".
  const showSweep = sweep !== null && reading.kind === 'idle'

  return (
    <section
      className="stg"
      data-animate={isLive ? 'on' : 'off'}
      data-focus={activeDivision ?? undefined}
      aria-labelledby="stage-title"
    >
      <div className="stg-veil" aria-hidden="true" />

      <div className="stg-inner">
        <header className="stg-head">
          <div>
            <p className="stg-eyebrow">Kabinet Abya Vistara · Periode {year}/{year + 1}</p>
            <h1 id="stage-title">
              Satu tahun, <span>{totalPrograms} program</span>, delapan bidang.
            </h1>
          </div>
          <p className="stg-lead">
            Sumbu mendatar adalah waktu, tiap pita adalah satu bidang, tiap balok adalah satu
            program di bulan ia benar-benar jatuh. Sentuh baloknya untuk membaca, klik untuk
            membuka halamannya.
          </p>
        </header>

        {/*
          Legenda, bukan bacaan. Papan ini memakai tiga tanda yang tidak bisa
          ditebak sendiri oleh pembaca — tebal balok, titik emas, garis emas —
          dan sampai sekarang tidak ada satu pun tempat yang menyebutkannya.
        */}
        <aside className="stg-key" aria-label="Cara membaca papan">
          <ul>
            <li>
              <i className="stg-key-solid" aria-hidden="true" />
              <span>
                <b>Tanggal pasti</b>
                {exactCount} program sudah punya tanggal, dan baloknya memenuhi jalurnya.
              </span>
            </li>
            <li>
              <i className="stg-key-thin" aria-hidden="true" />
              <span>
                <b>Baru bulan rencana</b>
                Balok lebih tipis: bulannya sudah ditetapkan, tanggalnya belum.
              </span>
            </li>
            <li>
              <i className="stg-key-dot" aria-hidden="true" />
              <span>
                <b>Program sorotan</b>
                Ditandai titik emas di ujung kanan baloknya.
              </span>
            </li>
            <li>
              <i className="stg-key-now" aria-hidden="true" />
              <span>
                <b>Hari ini</b>
                {now === null
                  ? `Tidak digambar: hari ini di luar tahun ${year}.`
                  : 'Garis emas tegak yang membelah papan.'}
              </span>
            </li>
          </ul>
        </aside>

        <div className="stg-scroll">
          <div
            className="stg-field"
            ref={fieldRef}
            style={
              {
                '--lane-h': `${LANE_HEIGHT}px`,
                '--lane-gap': `${LANE_GAP}px`,
              } as React.CSSProperties
            }
            onPointerMove={handlePointerMove}
            onPointerLeave={() => setSweep(null)}
          >
            <div className="stg-grid" aria-hidden="true">
              {MONTH_NAMES_SHORT.map((month) => (
                <i key={month} />
              ))}
            </div>

            {showSweep ? (
              <div
                className="stg-sweep"
                style={{ '--f': sweep } as React.CSSProperties}
                aria-hidden="true"
              >
                <b>{sweepMonth ? MONTH_NAMES_LONG[sweepMonth - 1] : ''}</b>
              </div>
            ) : null}

            {now !== null ? (
              <div
                className="stg-now"
                style={{ '--f': now } as React.CSSProperties}
                aria-hidden="true"
              >
                <b>Hari ini</b>
              </div>
            ) : null}

            <ol className="stg-rows">
              {rows.map((row, rowIndex) => (
                <StageRowView
                  key={row.division.code}
                  row={row}
                  rowIndex={rowIndex}
                  onRead={readBlock}
                  onClear={clearBlock}
                />
              ))}
            </ol>

            {/*
              Kartu bacaan. aria-hidden karena setiap baloknya sudah membawa
              teks lengkapnya sendiri lewat .sr-only, jadi pembaca layar sudah
              mendengar isinya tanpa kartu ini — dan mengumumkannya dua kali
              justru membuat papannya lebih sulit ditelusuri, bukan lebih mudah.
            */}
            {reading.kind === 'block' ? (
              <div
                className="stg-card"
                ref={cardRef}
                aria-hidden="true"
                data-div={reading.division.code}
                data-flip={cardTop !== null && cardTop < reading.top ? '' : undefined}
                key={reading.block.key}
                style={
                  {
                    left: `${reading.x}px`,
                    top: `${cardTop ?? reading.bottom + CARD_OFFSET}px`,
                    visibility: cardTop === null ? 'hidden' : undefined,
                    '--card-w': `${CARD_WIDTH}px`,
                  } as React.CSSProperties
                }
              >
                <span className="stg-card-div">{reading.division.name}</span>
                <strong>{reading.block.name}</strong>
                <span className="stg-card-when">{reading.block.scheduleLabel}</span>
                <p>{reading.block.desc}</p>
                <span className="stg-card-foot">
                  {reading.block.repeatCount > 1
                    ? `Berulang ${reading.block.repeatCount} kali setahun · `
                    : ''}
                  Klik untuk membuka halamannya
                </span>
              </div>
            ) : null}

            <ol className="stg-axis" aria-hidden="true">
              {MONTH_NAMES_SHORT.map((month, index) => (
                <li key={month} data-passed={now !== null && now > (index + 1) / 12}>
                  {month}
                </li>
              ))}
            </ol>
          </div>
        </div>

        {/*
          Dua kelompok yang tidak punya tempat di sumbu waktu, dan alasannya
          berbeda. Yang pertama karena tempatnya seluruh sumbu, yang kedua
          karena tempatnya belum ditetapkan. Keduanya tetap harus bisa diklik:
          kalau tidak, dua puluh sekian program cuma bisa ditemukan lewat
          katalog di bawah dan papan ini jadi setengah jujur.
        */}
        {ambientCount > 0 ? (
          <StageChips
            label={`Berjalan tiap bulan · ${ambientCount}`}
            note="Tidak digambar di papan karena tempatnya bukan satu bulan, melainkan semua."
            items={rows.flatMap((row) =>
              row.ambient.map((item) => ({ ...item, code: row.division.code })),
            )}
          />
        ) : null}

        {deferredCount > 0 ? (
          <StageChips
            label={`Belum punya bulan · ${deferredCount}`}
            note="Menunggu pengurus bidangnya menetapkan jadwal lewat panel."
            items={rows.flatMap((row) =>
              row.deferred.map((item) => ({ ...item, code: row.division.code })),
            )}
          />
        ) : null}

        <p className="stg-foot">
          {drawnBlocks} penanda digambar di papan. Program yang berjalan sepanjang dua belas bulan
          {deferredCount > 0 ? ' dan yang belum punya bulan' : ''} didaftar sebagai pil di atas,
          bukan digambar, karena tempatnya bukan satu titik di sumbu waktu.
        </p>
      </div>
    </section>
  )
}

function StageChips({
  label,
  note,
  items,
}: {
  label: string
  note: string
  items: Array<StageAmbient & { code: DivisionCode }>
}) {
  return (
    <div className="stg-chips">
      <div className="stg-chips-head">
        <span>{label}</span>
        <small>{note}</small>
      </div>
      <ul>
        {items.map((item) => (
          <li key={`${item.code}-${item.name}`} data-div={item.code}>
            <Link href={item.href}>
              <i aria-hidden="true" />
              {item.name}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  )
}

/*
 * memo() di sini bukan penghias.
 *
 * Menyorot satu balok memperbarui status di komponen induk, dan tanpa memo itu
 * berarti delapan baris berisi tiga puluh empat tautan dirender ulang setiap
 * kali kursor pindah balok — untuk mengubah satu kartu. Semua propnya sudah
 * stabil (`rows` lewat useMemo, kedua callback lewat useCallback), jadi memo
 * memotong seluruh render itu jadi nol.
 */
const StageRowView = memo(function StageRowView({
  row,
  rowIndex,
  onRead,
  onClear,
}: {
  row: StageRow
  rowIndex: number
  onRead: (block: StageBlock, division: Division, element: HTMLElement) => void
  onClear: () => void
}) {
  const height = row.laneCount * LANE_HEIGHT + (row.laneCount - 1) * LANE_GAP

  return (
    <li
      className="stg-row"
      data-div={row.division.code}
      style={
        {
          '--lanes': row.laneCount,
          '--row-h': `${height}px`,
          '--row-delay': `${rowIndex * 70}ms`,
        } as React.CSSProperties
      }
    >
      <span className="stg-row-label">
        <b>{row.division.shortName}</b>
        <small>{row.total} program</small>
        {row.ambient.length > 0 ? <em>+{row.ambient.length} rutin</em> : null}
      </span>

      {/*
        Program yang berjalan dua belas bulan penuh TIDAK digambar di papan sama
        sekali, dan itu keputusan yang sudah dua kali direvisi.

        Sebagai balok penuh, sebelas dari tiga puluh tujuh program menutupi
        seluruh papan dan menghapus bentuk tahunnya. Sebagai arsiran setinggi
        baris, lima dari delapan baris berubah jadi bidang bergaris dan balok
        yang lain tenggelam. Sebagai garis di dasar baris, ia terbaca sebagai
        pemisah baris, dan begitu itu terjadi papannya berubah jadi tabel.

        Yang tersisa dan benar: sebutkan jumlahnya di label barisnya, dan
        daftarkan namanya sebagai pil di bawah papan. Program yang berjalan tiap
        bulan memang tidak punya tempat di sumbu waktu, karena tempatnya adalah
        seluruh sumbu.
      */}
      <div className="stg-lanes">

        {row.blocks.map((block) => (
          <Link
            className="stg-block"
            key={block.key}
            href={block.href}
            data-precision={block.precision}
            data-label={block.repeatIndex === 0 ? block.labelPlacement : 'repeat'}
            data-featured={block.featured || undefined}
            style={
              {
                '--from': block.from,
                '--to': block.to,
                '--lane': block.lane,
                '--block-delay': `${rowIndex * 70 + Math.round(block.from * 420)}ms`,
              } as React.CSSProperties
            }
            onPointerEnter={(event) => onRead(block, row.division, event.currentTarget)}
            onPointerLeave={onClear}
            onFocus={(event) => onRead(block, row.division, event.currentTarget)}
            onBlur={onClear}
          >
            {/*
              Program yang berulang beberapa kali setahun hanya diberi nama di
              kemunculan pertamanya. Menulis "Bank Soal" empat kali di satu
              baris yang sama tidak menambah satu pun keterangan, dan barisnya
              berubah jadi pengulangan kata.
            */}
            <span className="stg-block-name" aria-hidden="true">
              {block.repeatIndex === 0 ? block.name : `${block.repeatIndex + 1}`}
            </span>
            <span className="sr-only">
              {block.name}, {row.division.name}, {block.scheduleLabel}
            </span>
          </Link>
        ))}
      </div>
    </li>
  )
})
